// Une classe de données classique : 30+ lignes pour dire "un point a un x et un y".
final class Point {
    private final int x;
    private final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    int x() { return x; }
    int y() { return y; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point other)) return false;
        return x == other.x && y == other.y;
    }

    @Override
    public int hashCode() {
        return java.util.Objects.hash(x, y);
    }

    @Override
    public String toString() {
        return "Point[x=" + x + ", y=" + y + "]";
    }
}

// Déclaration complète d'un record : une ligne.
record Point(int x, int y) { }

public class Demo {
    public static void main(String[] args) {
        // On crée une instance comme avec n'importe quelle classe : new + constructeur.
        Point p = new Point(3, 4);

        // Les accesseurs portent le nom du composant (x() et y()), PAS getX().
        System.out.println(p.x()); // 3
        System.out.println(p.y()); // 4

        // toString est déjà fourni, lisible et utile.
        System.out.println(p);     // Point[x=3, y=4]
    }
}

// Les composants peuvent être de n'importe quel type.
record Utilisateur(String nom, String email, int age) { }

record LigneCommande(String produit, int quantite, double prixUnitaire) { }

// Un record peut même porter d'autres records.
record Adresse(String rue, String ville, String codePostal) { }
record Client(String nom, Adresse adresse) { }

