record Point(int x, int y) { }

public class Demo {
    public static void main(String[] args) {
        Point a = new Point(3, 4);
        Point b = new Point(3, 4);
        Point c = new Point(9, 9);

        // Égalité par VALEUR, pas par référence : a et b ont les mêmes composants.
        System.out.println(a.equals(b)); // true
        System.out.println(a.equals(c)); // false

        // Du coup, un record s'utilise sans surprise comme clé de Map ou dans un Set.
        var vus = new java.util.HashSet<Point>();
        vus.add(a);
        System.out.println(vus.contains(b)); // true : b est "le même" que a
    }
}

record Utilisateur(String nom, String email, int age) {
    // Constructeur compact : PAS de parenthèses avec les paramètres.
    Utilisateur {
        // On vérifie, et on lève une exception si c'est invalide.
        if (nom == null || nom.isBlank()) {
            throw new IllegalArgumentException("nom obligatoire");
        }
        if (age < 0) {
            throw new IllegalArgumentException("age negatif interdit");
        }
        // Pas besoin d'écrire this.nom = nom; etc.
        // Le compilateur ajoute automatiquement les affectations APRÈS ce bloc.
    }
}

record Email(String valeur) {
    Email {
        if (valeur == null || !valeur.contains("@")) {
            throw new IllegalArgumentException("email invalide : " + valeur);
        }
        // Normalisation : on enlève les espaces et on met en minuscules.
        valeur = valeur.trim().toLowerCase();
    }
}

public class Demo {
    public static void main(String[] args) {
        Email e = new Email("  Jean.Dupont@Example.COM ");
        System.out.println(e.valeur()); // jean.dupont@example.com
    }
}

