record Point(int x, int y) {
    // On n'a pas de setX : on renvoie un NOUVEAU Point avec un x différent.
    Point withX(int nouveauX) {
        return new Point(nouveauX, y);
    }
}

public class Demo {
    public static void main(String[] args) {
        Point p1 = new Point(3, 4);
        Point p2 = p1.withX(10);

        System.out.println(p1); // Point[x=3, y=4]  (inchangé)
        System.out.println(p2); // Point[x=10, y=4] (nouvelle instance)
    }
}

