// Un record local, déclaré DANS une méthode : pratique pour un résultat ponctuel.
static MinMax bornes(int[] valeurs) {
    record MinMax(int min, int max) { }
    int min = valeurs[0], max = valeurs[0];
    for (int v : valeurs) {
        if (v < min) min = v;
        if (v > max) max = v;
    }
    return new MinMax(min, max);
}
// L'appelant lit resultat.min() et resultat.max() : clair et sans ambiguite.

interface Forme {
    double aire();
}

// Un record qui implémente une interface et ajoute ses propres méthodes.
record Cercle(double rayon) implements Forme {
    @Override
    public double aire() {
        return Math.PI * rayon * rayon;
    }

    // Méthode utilitaire supplémentaire.
    double diametre() {
        return rayon * 2;
    }
}
